using namespace std;
int main() {
    string s, ans = "";
    getline(cin, s);
    for (char c : s) {
        if (c >= '0' && c <= '9') {
            ans += c;
        } else if (ans.empty() || ans[ans.size() - 1] != '*') {
            ans += '*';
        }
    }
    cout << ans << endl;
    return 0;
}
