#include <bits/stdc++.h>
using namespace std;
int main() {
    int n;
    cin >> n;
    string names[105];
    for (int i = 0; i < n; ++i) cin >> names[i];
    for (int i = 0; i < n; ++i) {
        int k = i;
        for (int j = i + 1; j < n; ++j)
            if (names[j] < names[k]) k = j;
        swap(names[i], names[k]);
    }
    for (int i = 0; i < n; ++i) cout << names[i] << endl;
    return 0;
}
